-- Realistic 200-medicine sample inventory seed for Pharmacy Web Based.
-- Target DB: MySQL / MariaDB after the current Laravel migrations.
-- Uses the seeded company/branches, then inserts owner access, permissions, 200 medicines, branch inventories, and sample transactions.

START TRANSACTION;

SELECT @branch_1_id := branch_id
FROM branches
WHERE branch_name = 'Sto. Rosario Main Branch'
ORDER BY branch_id
LIMIT 1;

SELECT @branch_2_id := branch_id
FROM branches
WHERE branch_name = 'Sto. Rosario Main Branch 2'
ORDER BY branch_id
LIMIT 1;

  branch_id,
  first_name,
  last_name,
  email,
  password,
  status,
  role,
  address,
  login_at,
  registered_ip,
  last_login_ip,
  last_seen_ip,
  created_at,
  updated_at
) VALUES (
  @branch_1_id,
  'Store',
  'Owner',
  'owner@gmail.com',
  '$2y$12$tR7y8Sn.5iEmc1OgjSu5fuOtokyXLg/uCCOIBw1VMuWpXIIeruHO2',
  'approved',
  'owner',
  'Sto. Rosario, San Fernando, Pampanga',
  '2026-06-07 08:07:00',
  '127.0.0.1',
  '127.0.0.1',
  '127.0.0.1',
  '2026-06-07 08:07:00',
  '2026-06-07 08:07:00'
) ON DUPLICATE KEY UPDATE
  user_id = LAST_INSERT_ID(user_id),
  branch_id = VALUES(branch_id),
  first_name = VALUES(first_name),
  last_name = VALUES(last_name),
  password = VALUES(password),
  status = VALUES(status),
  role = VALUES(role),
  updated_at = VALUES(updated_at);
SET @owner_user_id := LAST_INSERT_ID();

ON DUPLICATE KEY UPDATE
  description = VALUES(description),
  updated_at = VALUES(updated_at);

SELECT @owner_user_id, permission_id, '2026-06-07 08:08:00', '2026-06-07 08:08:00'
FROM permissions
ON DUPLICATE KEY UPDATE updated_at = VALUES(updated_at);

SET @first_medicine_id := LAST_INSERT_ID();

SET @first_batch_id := LAST_INSERT_ID();



